import {profile,level,stats,NATURES,STAT_NAMES,candy,trainEV,trainIV,setNature} from './training.mjs';
import * as Art from './art.mjs';
export function worldHome(g){return `<section class="world-hero"><canvas id="world-art" width="960" height="360"></canvas><div class="world-hero-copy"><span class="eyebrow">UNE COLLECTION · MILLE AVENTURES</span><h1>Poké<span>World</span></h1><p>Retrouve tes Pokémon, retrouve tes amis.<br>Choisis ton prochain mini-jeu.</p><div><button class="primary" data-act="route" data-page="collection">Mes Pokémon →</button><button data-act="route" data-page="friends">Jouer avec mes amis</button></div><small>${g.state.roster.length} Pokémon · ${g.state.candies} bonbons · Tour étage ${g.state.floor}</small></div></section><div class="section-title world-section"><div><span class="eyebrow">À TOI DE JOUER</span><h2>Explore PokéWorld</h2></div><span>Une équipe partagée entre tous tes jeux</span></div><div class="world-games">${[
 ['tower','♜','La Tour Infernale','Affronte des dresseurs IA. Gagne chaque étage avec ton équipe de six.','DRESSEURS IA','4','tower-card'],
 ['den','◈','L’Antre','Défie des boss Pokémon, seul ou en raid avec jusqu’à quatre amis.','BOSS & COOPÉRATION','94','den-card'],
 ['survival','✦','Survie','Esquive les vagues, change d’attaque, ouvre des coffres et gagne de l’expérience.','ACTION & EXPLORATION','7','survival-card'],
 ['afk','◒','Pokéclick','Clique, recrute et développe ton camp. La production s’arrête quand tu quittes ce jeu.','CLICKER POKÉMON','25','click-card'],
 ['pvp','⚔','Combats Pokémon','Défie tes amis ou cherche un véritable joueur dans la file mondiale.','DUELS EN LIGNE','150','pvp-card'],
 ['gacha','✧','Portails d’invocation','Utilise tes tickets universels pour recruter des compagnons et découvrir des shinys.','INVOCATIONS ×1 & ×10','133','gacha-card']
 ].map(([page,mark,title,desc,label,key,cls])=>`<button class="world-game ${cls}" data-act="route" data-page="${page}"><span class="world-game-label">${label}</span><span class="world-game-mark">${mark}</span><canvas width="140" height="110" data-mon="${key}"></canvas><h2>${title}</h2><p>${desc}</p><strong>Jouer <span>↗</span></strong></button>`).join('')}</div><section class="panel world-progress"><div><span class="eyebrow">TES COMPAGNONS PROGRESSENT AVEC TOI</span><h2>Prépare ton équipe pour toutes les aventures</h2><p>Utilise les bonbons, entraîne les statistiques et personnalise les attaques de chaque Pokémon.</p></div><button class="primary" data-act="route" data-page="collection">Centre Pokémon →</button></section>`}
export function worldScene(ctx,w,h,t){ctx.imageSmoothingEnabled=false;ctx.fillStyle='#b6def0';ctx.fillRect(0,0,w,h);ctx.fillStyle='#e4f3ed';for(let i=0;i<7;i++){const x=(i*163+t*3)%1100-80,y=30+(i%3)*28;ctx.fillRect(x,y,65,13);ctx.fillRect(x+12,y-8,33,10)}ctx.fillStyle='#7bbaaf';for(let i=0;i<8;i++){ctx.beginPath();ctx.moveTo(i*160-60,230);ctx.lineTo(i*160+30,130+(i%2)*20);ctx.lineTo(i*160+160,230);ctx.fill()}ctx.fillStyle='#79bda3';ctx.fillRect(0,205,w,155);ctx.fillStyle='#a8ce92';ctx.fillRect(0,235,w,125);ctx.fillStyle='#e4cc98';ctx.fillRect(0,297,w,23);ctx.fillRect(635,220,26,140);for(let i=0;i<80;i++){ctx.fillStyle=i%3?'#91b77c':'#cee19c';ctx.fillRect((i*109)%w,245+(i*47)%110,3,2)}const house=(x,y,wall,roof)=>{ctx.fillStyle='#7da985';ctx.fillRect(x-5,y+52,112,9);ctx.fillStyle=wall;ctx.fillRect(x,y,100,54);ctx.fillStyle=roof;ctx.fillRect(x-8,y-10,116,15);ctx.fillRect(x,y-18,100,10);ctx.fillStyle='#d9eff1';ctx.fillRect(x+12,y+10,21,19);ctx.fillRect(x+67,y+10,21,19);ctx.fillStyle='#6c8894';ctx.fillRect(x+42,y+23,19,31)};house(570,201,'#f4eee0','#d77d76');house(770,225,'#e8e3d9','#8293c9');ctx.fillStyle='#547e7b';ctx.fillRect(714,136,40,100);ctx.fillStyle='#789491';for(let i=0;i<4;i++)ctx.fillRect(709+i*13,125,9,19);ctx.fillStyle='#f6d389';ctx.fillRect(730,164,9,15);for(const x of [510,880,930]){ctx.fillStyle='#8d8b68';ctx.fillRect(x,233,7,36);ctx.fillStyle='#689b75';ctx.fillRect(x-16,213,40,33);ctx.fillStyle='#81b287';ctx.fillRect(x-9,204,26,33)}Art.drawMon(ctx,'25',675,284,54,'Walk',6,t);Art.drawMon(ctx,'1',850,323,55,'Idle',0,t);Art.drawMon(ctx,'7',570,330,52,'Idle',0,t)}
export function denPage(g){return g.heading('UNE EXPÉDITION ENTRE AMIS','L’Antre','Affronte un boss géant avec ton équipe. Le boss ne peut viser qu’un Pokémon actif à la fois.')+`<section class="panel den-intro"><canvas width="260" height="210" data-mon="${[94,6,249,150,384,487].filter(id=>g.dex[id])[(g.state.denFloor-1)%[94,6,249,150,384,487].filter(id=>g.dex[id]).length]}"></canvas><div><span class="eyebrow">BOSS ${g.state.denFloor} · SOLO OU RAID À 4</span><h2>Une équipe pour vaincre le gardien</h2><p>Chaque dresseur apporte jusqu’à six Pokémon. Les boss deviennent plus forts à chaque victoire.</p><button class="primary" data-act="start-den">Entrer dans l’Antre ↗</button><button data-act="route" data-page="friends">Créer un raid entre amis</button></div></section>`}
export class PokemonLab {
 constructor(g){this.g=g}
 open(key){if(!this.g.state.roster.includes(key))return;this.key=key;const g=this.g,d=g.poke(key),p=profile(g.state,key),L=level(p),s=stats(g.dex,key,p),nature=NATURES.find(n=>n.id===p.nature)||NATURES[0];g.openModal(`<div class="pokemon-lab"><div class="lab-top">${g.image(key,'lab-mon')}<div><span class="rarity-tag ${d.rarity}">${g.rarity(d.rarity).name}${key.endsWith('s')?' · ✧ SHINY':''}</span><h2>${d.name} <small>Niv. ${L}</small></h2><p>${d.types.map(t=>Art.TYPE_NAMES[t]).join(' / ')} · ${nature.name}</p><span>${g.state.candies} bonbons · ${g.state.coins} fragments</span></div></div><section class="lab-level"><div><b>Expérience ${p.xp.toLocaleString('fr')} / ${L===100?'MAX':((L+1)**3).toLocaleString('fr')}</b><i><em style="width:${L===100?100:(p.xp-L**3)/((L+1)**3-L**3)*100}%"></em></i><small>Les mini-jeux accordent de l’XP et des bonbons. 1 bonbon = 100 XP.</small></div><button class="primary" data-act="train-candy" data-count="1" ${g.state.candies<1||L===100?'disabled':''}>+100 XP · 1 bonbon</button><button data-act="train-candy" data-count="10" ${g.state.candies<10||L===100?'disabled':''}>×10 bonbons</button></section><div class="lab-section-title"><h3>Statistiques & entraînement</h3><small>EV ${p.ev.reduce((s,n)=>s+n,0)} / 510 · 252 max par stat · IV 31 max</small></div><div class="lab-stats">${STAT_NAMES.map((label,i)=>`<div><b>${label}</b><strong>${s[i]}</strong><small>EV ${p.ev[i]} · IV ${p.iv[i]}</small><button data-act="train-ev" data-index="${i}" ${g.state.coins<100||p.ev[i]>=252||p.ev.reduce((s,n)=>s+n,0)>=510?'disabled':''}>+10 EV · 100 ✦</button><button data-act="train-iv" data-index="${i}" ${g.state.coins<300||p.iv[i]>=31?'disabled':''}>+1 IV · 300 ✦</button></div>`).join('')}</div><section class="lab-custom"><div><h3>Nature</h3><select id="lab-nature">${NATURES.map(n=>`<option value="${n.id}" ${n.id===p.nature?'selected':''}>${n.name}${n.up>=0?' · +'+STAT_NAMES[n.up]+' / −'+STAT_NAMES[n.down]:' · Neutre'}</option>`).join('')}</select><button data-act="train-nature" ${g.state.coins<250?'disabled':''}>Changer · 250 fragments</button></div><div><h3>Talent</h3><select id="lab-ability">${(d.abilities||[]).map((a,i)=>`<option value="${i}" ${p.ability===i?'selected':''}>${a.name}</option>`).join('')}</select><button data-act="train-ability" ${g.state.coins<250||d.abilities?.length<2?'disabled':''}>Changer · 250 fragments</button><small>Les effets des talents sont propres aux combats qui les prennent en charge.</small></div></section><section class="lab-moves"><h3>Quatre attaques offensives</h3><div>${[0,1,2,3].map(i=>`<select id="lab-move-${i}" aria-label="Attaque ${i+1}">${d.learnset.map(m=>`<option value="${m.id}" ${m.id===(p.moves[i]||d.moves[i].id)?'selected':''}>${m.name} · ${Art.TYPE_NAMES[m.type]}</option>`).join('')}</select>`).join('')}</div><button data-act="train-moves">Enregistrer les attaques</button></section>${d.evolutions?.filter(e=>g.dex[e.id]).length?`<section class="lab-evolution"><h3>Évolution</h3>${d.evolutions.filter(e=>g.dex[e.id]).map(e=>`<button data-act="train-evolve" data-id="${e.id}" ${L<e.level?'disabled':''}>Évoluer en ${g.dex[e.id].name} · niveau ${e.level}</button>`).join('')}<small>L’évolution conserve le niveau, l’entraînement et l’objet tenu.</small></section>`:''}</div>`)}
 action(kind,d){const g=this.g,key=this.key;if(!g.state.roster.includes(key))return;let ok=false;if(kind==='train-candy')ok=candy(g.state,key,+d.count);if(kind==='train-ev')ok=trainEV(g.state,key,+d.index);if(kind==='train-iv')ok=trainIV(g.state,key,+d.index);if(kind==='train-nature')ok=setNature(g.state,key,document.querySelector('#lab-nature').value);if(kind==='train-ability'){const i=+document.querySelector('#lab-ability').value,p=profile(g.state,key);if(g.state.coins>=250&&g.poke(key).abilities[i]&&p.ability!==i){g.state.coins-=250;p.ability=i;ok=true}}if(kind==='train-moves'){const ids=[0,1,2,3].map(i=>+document.querySelector('#lab-move-'+i).value);if(new Set(ids).size!==4)return g.toast('Choisis quatre attaques différentes.');profile(g.state,key).moves=ids;ok=true}if(kind==='train-evolve'){const e=g.poke(key).evolutions.find(e=>e.id===+d.id),p=profile(g.state,key),newKey=String(d.id)+(key.endsWith('s')?'s':'');if(e&&g.dex[e.id]&&level(p)>=e.level&&!g.state.roster.includes(newKey)){g.state.roster=g.state.roster.map(k=>k===key?newKey:k);g.state.team=g.state.team.map(k=>k===key?newKey:k);if(g.state.survivor===key)g.state.survivor=newKey;g.state.training[newKey]={...p,moves:[],ability:0};delete g.state.training[key];if(g.state.equipment[key]){g.state.equipment[newKey]=g.state.equipment[key];delete g.state.equipment[key]}this.key=newKey;ok=true}}if(ok){g.save();g.render();this.open(this.key);g.audio.tone(550,.07)}else g.toast('Cette amélioration n’est pas disponible pour le moment.')}
}
